{"content":"$ErrorActionPreference = 'Stop'
$Dir = $PSScriptRoot
$md = Join-Path $Dir 'chars\hutao.md'
$js = Join-Path $Dir 'chars\hutao.json'

function Get-BodyInfo([string]$p) {
  if (-not (Test-Path $p)) { return $null }
  $bytes = [System.IO.File]::ReadAllBytes($p)
  $text = [System.Text.Encoding]::UTF8.GetString($bytes)
  $idx = $text.LastIndexOf('EVIDENCE:')
  $info = [ordered]@{
    Path       = $p
    Bytes      = $bytes.Length
    HasEvidence = ($idx -ge 0)
    DeclaredBytes = $null
    DeclaredHash  = $null
    HashOk     = $false
    BytesOk    = $false
    TriedOffset = $null
    Body       = $null
  }
  if ($idx -lt 0) {
    $info.Body = $text
    return [pscustomobject]$info
  }
  $evLine = ($text.Substring($idx) -split "`r?`n")[0].Trim()
  $parts = $evLine -split '\|'
  if ($parts.Count -ge 3) {
    $info.DeclaredBytes = $parts[1].Trim()
    $info.DeclaredHash = $parts[2].Trim()
  }
  $prefixText = $text.Substring(0, $idx)
  $prefixBytesAll = [System.Text.Encoding]::UTF8.GetBytes($prefixText)
  foreach ($off in 0,1,2,3,4) {
    if ($prefixBytesAll.Length -lt $off) { continue }
    $len = $prefixBytesAll.Length - $off
    $slice = New-Object byte[] $len
    [System.Array]::Copy($prefixBytesAll, $slice, $len)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $hex = -join ($sha.ComputeHash($slice) | ForEach-Object { $_.ToString('x2') })
    $sha.Dispose()
    if ($info.DeclaredHash -and $hex.StartsWith($info.DeclaredHash)) {
      $info.HashOk = $true
      $info.TriedOffset = $off
      if ($info.DeclaredBytes -and ([int]$info.DeclaredBytes -eq $len)) { $info.BytesOk = $true }
      $info.Body = [System.Text.Encoding]::UTF8.GetString($slice)
      break
    }
  }
  if (-not $info.Body) {
    $info.Body = $prefixText
    if ($info.DeclaredBytes -and ([int]$info.DeclaredBytes -eq $prefixBytesAll.Length)) { $info.BytesOk = $true }
  }
  if ($info.TriedOffset -ne $null -and $info.TriedOffset -ne 0) {
    if (-not $info.BytesOk -and $prefixBytesAll.Length - $info.TriedOffset * 0 -eq 0) { }
  }
  if ($info.DeclaredBytes) {
    foreach ($off in 0,1,2,3,4) {
      $len = $prefixBytesAll.Length - $off
      if ([int]$info.DeclaredBytes -eq $len) { $info.BytesOk = $true }
    }
  }
  return [pscustomobject]$info
}

$report = New-Object System.Collections.ArrayList

# ---- markdown ----
if (Test-Path $md) {
  $m = Get-BodyInfo $md
  $body = $m.Body
  $heads = @('## 1 ','## 2 ','## 3 ','## 4 ','## 5 ')
  $headFound = @()
  foreach ($h in $heads) { $headFound += [bool]($body -match [regex]::Escape($h)) }
  $tableLines = ($body -split "`r?`n" | Where-Object { $_.TrimStart().StartsWith('|') })
  $brCount = ([regex]::Matches($body, '<br')).Count
  $tildeCount = ([regex]::Matches($body, '(?<![0-9A-Za-z])~(?![~])')).Count
  $evCount = ([regex]::Matches($body, 'EVIDENCE:')).Count
  [void]$report.Add([pscustomobject]@{
    Item = 'md.exists'; Value = $true; Note = $md
  })
  [void]$report.Add([pscustomobject]@{ Item='md.bytes'; Value=$m.Bytes; Note=('declared=' + $m.DeclaredBytes) })
  [void]$report.Add([pscustomobject]@{ Item='md.evidenceLine'; Value=$m.HasEvidence; Note=('hashOk=' + $m.HashOk + '; bytesOk=' + $m.BytesOk + '; offset=' + $m.TriedOffset) })
  [void]$report.Add([pscustomobject]@{ Item='md.headings'; Value=($headFound -join ','); Note='1..5 全 true 才算齐' })
  [void]$report.Add([pscustomobject]@{ Item='md.tableRows'; Value=$tableLines.Count; Note='表格行数' })
  [void]$report.Add([pscustomobject]@{ Item='md.brInBody'; Value=$brCount; Note='必须 0' })
  [void]$report.Add([pscustomobject]@{ Item='md.asciiTilde'; Value=$tildeCount; Note='正文半角波浪号计数，宜 0' })
  [void]$report.Add([pscustomobject]@{ Item='md.strayEvidence'; Value=$evCount; Note='正文里不应再出现 EVIDENCE' })
  $longCells = 0
  foreach ($l in $tableLines) { if ($l.Length -gt 300) { $longCells++ } }
  [void]$report.Add([pscustomobject]@{ Item='md.longTableRows'; Value=$longCells; Note='超过 300 字的表格行数' })
} else {
  [void]$report.Add([pscustomobject]@{ Item='md.exists'; Value=$false; Note=$md })
}

# ---- json ----
if (Test-Path $js) {
  $j = Get-BodyInfo $js
  $raw = [System.IO.File]::ReadAllText($js, [System.Text.Encoding]::UTF8)
  $idx = $raw.LastIndexOf('EVIDENCE:')
  $stripped = if ($idx -ge 0) { $raw.Substring(0, $idx).TrimEnd() } else { $raw.TrimEnd() }
  $parsed = $null
  $err = ''
  try { $parsed = $stripped | ConvertFrom-Json } catch { $err = $_.Exception.Message }
  [void]$report.Add([pscustomobject]@{ Item='json.bytes'; Value=$j.Bytes; Note=('declared=' + $j.DeclaredBytes) })
  [void]$report.Add([pscustomobject]@{ Item='json.evidenceLine'; Value=$j.HasEvidence; Note=('hashOk=' + $j.HashOk + '; bytesOk=' + $j.BytesOk) })
  [void]$report.Add([pscustomobject]@{ Item='json.parses'; Value=[bool]$parsed; Note=$err })
  if ($parsed) {
    [void]$report.Add([pscustomobject]@{ Item='json.changes'; Value=$parsed.changes.Count; Note='应为 6' })
    [void]$report.Add([pscustomobject]@{ Item='json.unknowns'; Value=$parsed.unknowns.Count; Note='应 >= 7' })
    [void]$report.Add([pscustomobject]@{ Item='json.sources'; Value=$parsed.sources.Count; Note='应 >= 8' })
    [void]$report.Add([pscustomobject]@{ Item='json.slots'; Value=(($parsed.changes | ForEach-Object { $_.slot }) -join ','); Note='应含 system_da_quan,hp_threshold,C1,C2,C4,C6' })
    $news = ($parsed.changes | ForEach-Object { $_.new }) -join ' / '
    [void]$report.Add([pscustomobject]@{ Item='json.newValues'; Value=$news; Note='? 应保留' })
  }
} else {
  [void]$report.Add([pscustomobject]@{ Item='json.exists'; Value=$false; Note=$js })
}

$report | Format-Table -AutoSize -Wrap
","file_path":"./"}

